// Law: lawtwin.kafka.contract::Broker: read-committed fetches never see open or aborted
// transactions [reference]
// Description: While a transaction is open its records are past the last stable
// offset, which read-committed consumers do not pass. Once it aborts its
// records are skipped for ever. Read-uncommitted consumers see them both
// times.
// Rationale:
// References: KIP-98
// Expansion:
// Broker: read-committed fetches never see open or aborted transactions [reference]
// for all (t :: Text) (txid :: Text) (batch :: List (lawtwin.kafka.model::type::Record)) .
// (createTopicsRequest (_input0) (1) == Either::Right(unitValue)) implies transactionThenRead
// (_input0) (_input1) (_input2) (false) = true
fn law_11(
    ctx: &mut ls::Context,
    input_0: ls::Value,
    input_1: ls::Value,
    input_2: ls::Value,
) -> ls::Result<()> {
    ctx.install_handlers(vec![
        ("lawtwin.kafka.contract::ability::Broker".to_string(), ls::installed(std::sync::Arc::new(lawspec_abilities::lawtwin_kafka_contract::Reference::new(ctx)) as std::sync::Arc<dyn lawspec_abilities::lawtwin_kafka_contract::Broker>)),
    ]);
    let input_0 = lawspec_schema::schema()?.validate_with_context(
        input_0,
        &ls::TypeRef::named("Text", vec![]),
        64,
        ctx,
    )?;
    let input_1 = lawspec_schema::schema()?.validate_with_context(
        input_1,
        &ls::TypeRef::named("Text", vec![]),
        64,
        ctx,
    )?;
    let input_2 = lawspec_schema::schema()?.validate_with_context(
        input_2,
        &ls::TypeRef::named(
            "List",
            vec![ls::TypeRef::named(
                "lawtwin.kafka.model::type::Record",
                vec![],
            )],
        ),
        64,
        ctx,
    )?;
    {
        let condition = {
            let left = {
                let perform_argument_0 = input_0.clone();
                let perform_argument_1 = ls::Value::Integer(1i128.into());
                let arguments = vec![perform_argument_0, perform_argument_1];
                let result = lawspec_abilities::lawtwin_kafka_contract::perform_createTopicsRequest(
                    ctx,
                    arguments,
                );
                let context = "createTopicsRequest";
                result.map_err(|error| format!("{context}: {error}"))?
            };
            let right = ls::construct("Either::Right", vec![ls::Value::Unit])?;
            ls::binary(
                "==",
                "Either lawtwin.kafka.model::type::KafkaError Unit",
                left,
                right,
            )?
        };
        if condition.boolean()? {
            {
                let left = {
                    let call_argument_0 = input_0.clone();
                    let call_argument_1 = input_1.clone();
                    let call_argument_2 = input_2.clone();
                    let call_argument_3 = ls::Value::Bool(false);
                    let arguments = vec![
                        call_argument_0,
                        call_argument_1,
                        call_argument_2,
                        call_argument_3,
                    ];
                    let result = lawspec_definitions::evaluate_340(ctx, arguments);
                    let context = "lawtwin.kafka.contract::transactionThenRead";
                    result.map_err(|error| format!("{context}: {error}"))?
                };
                let right = ls::Value::Bool(true);
                if !ls::equal(&left, &right)? {
                    return Err(format!(
                        "{}: {:?} != {:?}{}",
                        concat!(
                            "Broker: read-committed fetches never see open ",
                            "or aborted transactions [reference] | expect t",
                            "ransactionThenRead (_input0) (_input1) (_input",
                            "2) (false) = true",
                        ),
                        left,
                        right,
                        ls::difference(&left, &right),
                    ));
                }
            }
        }
    }
    Ok(())
}

